   415	sub logical_width_for_output {
   416	    my ($output_mode, $output_name) = @_;
   417	    return 0 if !defined $output_mode || $output_mode !~ /\A(\d+)x\d+@/;
   418	
   419	    my $physical_width = int($1);
   420	    my $output_scale = scale_for_output($output_name);
   421	    return int(($physical_width / $output_scale) + 0.5);
   422	}
