   430	sub best_mode {
   431	    my ($modes, $preferred_hz) = @_;
   432	    return undef if !@{$modes};
   433	
   434	    my @sorted = sort {
   435	        mode_sort_key($a, $preferred_hz) <=> mode_sort_key($b, $preferred_hz)
   436	          ||
   437	        $b->{hz} <=> $a->{hz}
   438	    } @{$modes};
   439	
   440	    return $sorted[0];
   441	}
