   454	        $scale_value = $defaults{LABWC_OUTPUT_INTERNAL_SCALE} // $defaults{LABWC_OUTPUT_SCALE} // '1';
   455	    } else {
   456	        $scale_value = $defaults{LABWC_OUTPUT_EXTERNAL_SCALE} // $defaults{LABWC_OUTPUT_SCALE} // '1';
   457	    }
   458	
   459	    return '1'
   460	      if $scale_value !~ /\A\d+(?:\.\d+)?\z/
   461	      || $scale_value < 0.5
   462	      || $scale_value > 3;
