from collections import Counter
from pathlib import Path
import re

field = re.compile(r"(?P<key>[A-Za-z_][A-Za-z0-9_]*)=(?:\"(?P<quoted>[^\"]*)\"|(?P<bare>[^\s\x1d]+))")
managed = "managed-labwc-managed-app//managed-app-bwrap"
