unknown = Counter()
for number, line in enumerate(Path("apparmor.log").open(encoding="utf-8", errors="replace"), 1):
    if "denied_mask=" not in line:
        continue
    data = {m.group("key"): m.group("quoted") if m.group("quoted") is not None else m.group("bare") for m in field.finditer(line)}
    profile, op, name = data.get("profile", ""), data.get("operation", ""), data.get("name", "")
    cat = None
    if profile == managed and op in {"create", "bind", "connect", "sendmsg", "recvmsg", "receive", "send"} and data.get("family") in {"inet", "inet6"} and data.get("sock_type") in {"stream", "dgram"}:
        cat = "managed_bwrap_network"
