        cat = "managed_bwrap_accelerometer_probe"
    elif profile == managed and op == "open" and name.startswith("/proc/"):
        cat = "managed_bwrap_proc_runtime"
    elif profile == managed and op in {"open", "create", "file_perm"} and name.startswith("/dev/shm/"):
        cat = "managed_bwrap_shared_memory"
    elif profile == "filen" and op == "open" and re.fullmatch(r"/proc/[0-9]+/comm", name):
        cat = "filen_process_comm"
    elif profile == "sqlitebrowser" and op == "link" and re.fullmatch(r"/home/[^/]+/[.]config(?:/sqlitebrowser)?/(?:#\d+|sqlitebrowser[.]conf|QtProject[.]conf)", name):
        cat = "sqlitebrowser_atomic_link"
    if cat:
        counts[cat] += 1
    else:
        unknown[(profile, op, data.get("family", ""), data.get("sock_type", ""), name)] += 1
print("categories")
for key, value in sorted(counts.items()):
